poll_amiga_mouse_and_joystick_controls:
	lea.l PLAT_AMIGA_CUSTOM_BASE.l,a5
	moveq.l #0,d0
	move.b $00BFE0FF.l,d0
	btst #6,d0
	seq.b SG2InputWorkspace_mouse_primary_button_flag(a6)
	btst #7,d0
	seq.b SG2InputWorkspace_primary_fire_flag(a6)
	move.w PLAT_AMIGA_CUSTOM_POTINP_OFFSET(a5),d0
	btst #10,d0
	seq.b SG2InputWorkspace_mouse_secondary_button_flag(a6)
	move.w #$C00,PLAT_AMIGA_CUSTOM_POTGO_OFFSET(a5)
	clr.w d2
	move.w PLAT_AMIGA_CUSTOM_JOY1DAT_OFFSET(a5),d0	; joystick/mouse port 1 data
	btst #1,d0
	beq.b .test_left_bit
	addq.w #8,d2
.test_left_bit:
	btst #9,d0
	beq.b .decode_vertical
	addq.w #4,d2
.decode_vertical:
	move.w d0,d1
	asr.w #1,d1
	eor.w d1,d0
	btst #0,d0
	beq.b .test_up_bit
	addq.w #2,d2
.test_up_bit:
	btst #8,d0
	beq.b .store_joystick
	addq.w #1,d2
.store_joystick:
	move.w d2,SG2InputWorkspace_joystick_direction_bits(a6)
	move.w PLAT_AMIGA_CUSTOM_JOY0DAT_OFFSET(a5),d0	; joystick/mouse port 0 data
	move.w d0,d1
	andi.w #255,d0
	clr.w d2
	move.b SG2InputWorkspace_amiga_mouse_previous_x_counter(a6),d2
	move.b d1,SG2InputWorkspace_amiga_mouse_previous_x_counter(a6)
	sub.w d2,d0
	cmp.w #$7F,d0
	bmi.b .test_x_underflow
	subi.w #255,d0
	bra.b .decode_y_delta
.test_x_underflow:
	cmp.w #$FF81,d0
	bpl.b .decode_y_delta
	addi.w #255,d0
.decode_y_delta:
	move.w d0,d6
	asr.w #8,d1
	move.w d1,d0
	andi.w #255,d0
	clr.w d2
	move.b SG2InputWorkspace_amiga_mouse_previous_y_counter(a6),d2
	move.b d1,SG2InputWorkspace_amiga_mouse_previous_y_counter(a6)
	sub.w d2,d0
	cmp.w #$7F,d0
	bmi.b .test_y_underflow
	subi.w #255,d0
	bra.b .apply_motion
.test_y_underflow:
	cmp.w #$FF81,d0
	bpl.b .apply_motion
	addi.w #255,d0
.apply_motion:
	move.w SG2InputWorkspace_mouse_input_scale_shift(a6),d1
	tst.b SG2WorkspaceReferencePrefix_free_flight_controls_enabled_flag(a6)
	bpl.b .done
	tst.b SG2ContactWorkspace_structure_contact_pose_mode(a6)
	bne.b .done
	tst.b SG2InputWorkspace_mouse_secondary_button_flag(a6)
	beq.b .pitch
	add.w d0,SG2WorkspaceReferencePrefix_negative_speed_control_accumulator(a6)
	bra.b .scale_yaw
.pitch:
	ext.l d0
	add.w d0,SG2PlayerMotionWorkspace_rotation_0_control_accumulator(a6)
.scale_yaw:
	ext.l d6
	lsl.l #4,d6
	asr.l d1,d6
	tst.b SG2WorkspaceReferencePrefix_space_environment_flag(a6)
	bpl.b .yaw
	asr.l #2,d6
.yaw:
	add.w d6,SG2PlayerMotionWorkspace_rotation_2_control_accumulator(a6)
.done:
	rts
